n = int(input())
q_s = list(map(int, input().split()))
a_s = list(map(int, input().split()))
b_s = list(map(int, input().split()))

max_num = 0

for number_of_a in range(min(q_s[i] // a_s[i] if a_s[i] != 0 else float('inf') for i in range(n)) + 1):
    number_of_b = float('inf')
    for j in range(n):
        if b_s[j] != 0:
            number_of_b = min(number_of_b, (q_s[j] - a_s[j] * number_of_a) // b_s[j])
    if number_of_b >= 0:
        max_num = max(max_num, number_of_a + number_of_b)

print(max_num)
